public HelpWindow(string? anchor = null, string? scrollToTitle = null)          {              InitializeComponent();                // Single-File 公開時は AppDomain.CurrentDomain.BaseDirectory が exe と同じディレクトリを指す。              // ファイル名は実ディスクと完全一致 (lowercase) させて WebView2 の URI 解決を確実にする。              _baseFilePath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "Help", "help.html");              _pendingScrollTitle = scrollToTitle;              _pendingAnchorId = anchor;                // ファイル存在チェック (publish 時の見落とし検出)              if (!File.Exists(_baseFilePath))              {                  Log.Warning("[HelpWindow] help.html が見つかりません: {Path}", _baseFilePath);                  MessageBox.Show($"ヘルプファイルが見つかりません。
{_baseFilePath}

アプリケーションが正しく配置されていない可能性があります。",                      "ヘルプエラー", MessageBoxButton.OK, MessageBoxImage.Warning);                  return;              }                // WebView2 Runtime インストール確認 (Evergreen Runtime が無いと WebView2 がクラッシュする)              if (!Services.WebView2RuntimeChecker.IsRuntimeInstalled())              {                  Services.WebView2RuntimeChecker.ShowMissingRuntimeDialog();                  return;              }                HelpWebView.Source = BuildUri(anchor);                HelpWebView.NavigationCompleted += async (s, e) =>              {                  try                  {                      if (!e.IsSuccess) return;                        var version = ViewModels.MainWindowViewModel.AppVersion;                      try                      {                          // バージョンテキスト設定と同時に visibility:visible へ。                          // help.html 側で初期値 visibility:hidden にしているため、                          // 古い (誤った) バージョン文字列が一瞬見える問題が解消される。                          await HelpWebView.ExecuteScriptAsync($@"                              var el = document.getElementById('app-version');                              if (el) {{                                  el.textContent = 'ver {version}';                                  el.style.visibility = 'visible';                              }}                          ");                      }                      catch (Exception scriptEx)                      {                          Log.Warning(scriptEx, "[HelpWindow] バージョン更新スクリプト失敗");                      }                        // 初回ロード時は WebView2 / DOMContentLoaded / numberHeadings 完了を JS 側で polling して待つ。                      if (!string.IsNullOrEmpty(_pendingAnchorId) || !string.IsNullOrEmpty(_pendingScrollTitle))                      {                          var anchorId = _pendingAnchorId ?? "";                          var scrollTitle = _pendingScrollTitle ?? "";                          _pendingAnchorId = null;                          _pendingScrollTitle = null;                          await WaitAndScrollAsync(anchorId, scrollTitle);                      }                  }                  catch (Exception navEx)                  {                      // NavigationCompleted は WebView2 内部スレッドから fire されることがある。                      // ここで例外を漏らすと AppDomain.UnhandledException 経由でアプリがダウンする可能性がある。                      Log.Warning(navEx, "[HelpWindow] NavigationCompleted ハンドラ例外");                  }              };          }

