public App()         {             // ロギングを最優先で初期化 (それ自身が失敗しても続行)             AppLog.Initialize();              // 全 3 ソースの未捕捉例外をフック             this.DispatcherUnhandledException += App_DispatcherUnhandledException;             AppDomain.CurrentDomain.UnhandledException += AppDomain_UnhandledException;             TaskScheduler.UnobservedTaskException += TaskScheduler_UnobservedTaskException;              try             {                 Log.Information("App constructor start");                  var mainWindowViewModel = new MainWindowViewModel();                 CurrentMainViewModel = mainWindowViewModel;                 InputModel = new InputModel();                 InputModel.SetMainWindowViewModel(mainWindowViewModel);                  Log.Information("App constructor complete");             }             catch (Exception ex)             {                 Log.Fatal(ex, "App constructor failed");                 MessageService.Show(                     $"アプリ起動時に致命的なエラーが発生しました。
{ex.Message}

ログ: {AppLog.LogDirectory}",                     "起動エラー", MessageBoxButton.OK, MessageBoxImage.Error);                 AppLog.Close();                 Environment.Exit(1);             }         }

